def word_frequency(text: str) -> Dict[str, int]:
    """Return a dict that maps each lowercase word in text to how often it appears."""
    # Remove all non-alphanumeric characters and split the text into words
    words = [word for word in text.split() if word.isalnum()]

    # Convert all words to lowercase to ensure case insensitivity
    words = [word.lower() for word in words]

    # Use a dictionary to count occurrences
    word_count = {word: words.count(word) for word in words}

