def group_anagrams(words: list[str]) -> list[list[str]]:
    """Group words that are anagrams; sort each group, then sort the groups."""
    group = []
    for word in words:
        # Create a sorted version of the word
        sorted_word = ''.join(sorted(word))
        # If the sorted word is already in the group, append the word to the group
        if sorted_word in group:
            group[group.index(sorted_word)].append(word)
        # Otherwise, create a new group with this sorted word and append the word
        else:
            group.append([sorted_word, word])
    # Sort the groups by the first word and return them
    return sorted(group, key=lambda x: x[0])
