def group_anagrams(words: list[str]) -> list[list[str]]:
    def sort_word(word):
        return ''.join(sorted(word))

    def group_anagrams_by_word(word):
        return [word]

    group_by_word_results = {}
    for word in words:
        sorted_word = sort_word(word)
        if sorted_word in group_by_word_results:
            group_by_word_results[sorted_word].append(word)
        else:
            group_by_word_results[sorted_word] = [word]

    grouped_results = []
    for groups in group_by_word_results.values():
        grouped_results.append(groups)

    return grouped_results

